-- SELECT only. Save before apply. System catalogs and the migration history only (no app table rows).
-- 바뀌는 것 전부의 되돌릴 기준: 새 함수(적용 전엔 없음), 이 함수가 읽는 표들의 칸 목록·RLS·권한·정책·트리거(이 migration은 건드리지 않음을 대조), 기록.
select 'function' as kind,p.oid::regprocedure::text as name,p.prosecdef::text||':'||coalesce(p.proconfig::text,'none')||':'||coalesce(p.proacl::text,'none')||':'||md5(p.prosrc) as definition
  from pg_proc p where p.oid in(to_regprocedure('public.app_call_context_people(uuid,integer)'),to_regprocedure('public.app_call_edit(uuid,jsonb)'))
union all select 'trigger',c.relname::text||'.'||t.tgname::text,t.tgenabled::text||':'||pg_get_triggerdef(t.oid) from pg_trigger t join pg_class c on c.oid=t.tgrelid where t.tgrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_edits'),to_regclass('public.app_suborganizations')) and not t.tgisinternal
union all select 'table',c.relname::text,c.relrowsecurity::text||':'||coalesce(c.relacl::text,'none') from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_suborganizations'))
union all select 'column',c.relname::text||'.'||a.attname::text,format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull::text||':'||a.atthasdef::text||':'||coalesce(a.attacl::text,'none') from pg_attribute a join pg_class c on c.oid=a.attrelid where a.attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_suborganizations')) and a.attnum>0 and not a.attisdropped
union all select 'policy',p.polrelid::regclass::text||'.'||p.polname::text,p.polcmd::text||':'||p.polroles::text||':'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||':'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),'') from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_suborganizations'))
union all select 'history',version,name from supabase_migrations.schema_migrations where version in('20261026120000','20261026160000')
order by 1,2;
